@Component("enterprise-handler")
@ProcessingGroup("enterprise-processing-group")
public class EnterpriseEventHandler {
	
	// core constructor
	EnterpriseEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateEnterpriseEvent
     */
    @EventHandler
    public void handle( CreateEnterpriseEvent event) {
        entityManager.persist(new Enterprise(event.getEnterpriseId(), event.getName(), event.getLegalName(), event.getRegistrationCountry(), event.getWebsite(), event.getTaxId(), event.getBusinessUnits(), event.getPlants(), event.getSuppliers(), event.getCustomers()));
    }

    /*
     * @param	event UpdateEnterpriseEvent
     */
    @EventHandler
    public Enterprise handle( UpdateEnterpriseEvent event) {
    	entityManager.merge(new Enterprise(event.getEnterpriseId(), event.getName(), event.getLegalName(), event.getRegistrationCountry(), event.getWebsite(), event.getTaxId(), event.getBusinessUnits(), event.getPlants(), event.getSuppliers(), event.getCustomers()));
    }
    
    /*
     * @param	event DeleteEnterpriseEvent
     */
    @EventHandler
    public void on( DeleteEnterpriseEvent event) {
    	Enterprise entity = new Enterprise();
   
    	// ------------------------------------------
    	// apply the EnterpriseId
    	// ------------------------------------------
    	entity.setEnterpriseId( event.getEnterpriseId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final EnterpriseRepository enterpriseEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(EnterpriseEventHandler.class.getName());

}
